#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

#define MAX_ENTRIES 64
#define ENTRY_SIZE 256

typedef struct {
    char *name;
    char *value;
    int active;
} ConfigEntry;

typedef struct {
    ConfigEntry entries[MAX_ENTRIES];
    int count;
    char *scratch_file;
} ConfigStore;

static ConfigStore *g_store = NULL;

void store_init(void) {
    g_store = (ConfigStore *)calloc(1, sizeof(ConfigStore));
    g_store->count = 0;
    g_store->scratch_file = strdup("/tmp/.cfg_scratch");
}

void store_add(const char *name, const char *value) {
    if (g_store->count >= MAX_ENTRIES) return;
    int idx = g_store->count++;
    g_store->entries[idx].name = strdup(name);
    g_store->entries[idx].value = strdup(value);
    g_store->entries[idx].active = 1;
}

void store_remove(const char *name) {
    for (int i = 0; i < g_store->count; i++) {
        if (g_store->entries[i].active && strcmp(g_store->entries[i].name, name) == 0) {
            free(g_store->entries[i].name);
            free(g_store->entries[i].value);
            g_store->entries[i].active = 0;
            /* BUG: pointers not NULLed after free */
            break;
        }
    }
}

char *store_get(const char *name) {
    for (int i = 0; i < g_store->count; i++) {
        if (g_store->entries[i].active && strcmp(g_store->entries[i].name, name) == 0) {
            return g_store->entries[i].value;
        }
    }
    return NULL;
}

void store_update_dangling(const char *name, const char *new_value) {
    /* Iterates ALL entries including inactive - uses dangling pointer */
    for (int i = 0; i < g_store->count; i++) {
        if (strcmp(g_store->entries[i].name, name) == 0) {
            /* UAF: entries[i].name was freed but pointer still compared */
            /* If heap is reused, this reads attacker-controlled data */
            free(g_store->entries[i].value);
            g_store->entries[i].value = strdup(new_value);
            g_store->entries[i].active = 1;
            break;
        }
    }
}

void persist_to_scratch(void) {
    FILE *f = fopen(g_store->scratch_file, "w");
    if (!f) {
        fprintf(stderr, "Warning: cannot write scratch file %s\n", g_store->scratch_file);
        return;
    }
    for (int i = 0; i < g_store->count; i++) {
        if (g_store->entries[i].active) {
            fprintf(f, "%s=%s\n", g_store->entries[i].name, g_store->entries[i].value);
        }
    }
    fclose(f);
}

int process_command(char *line) {
    char cmd[32], arg1[ENTRY_SIZE], arg2[ENTRY_SIZE];
    int n = sscanf(line, "%31s %255s %255[^\n]", cmd, arg1, arg2);
    if (n < 1) return 0;

    if (strcmp(cmd, "ADD") == 0 && n >= 3) {
        store_add(arg1, arg2);
    } else if (strcmp(cmd, "DEL") == 0 && n >= 2) {
        store_remove(arg1);
    } else if (strcmp(cmd, "GET") == 0 && n >= 2) {
        char *v = store_get(arg1);
        if (v) printf("%s\n", v);
    } else if (strcmp(cmd, "UPDATE") == 0 && n >= 3) {
        store_update_dangling(arg1, arg2);
    } else if (strcmp(cmd, "SAVE") == 0) {
        persist_to_scratch();
    } else if (strcmp(cmd, "QUIT") == 0) {
        return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    store_init();
    char line[512];
    FILE *input = stdin;
    if (argc > 1) {
        input = fopen(argv[1], "r");
        if (!input) { perror("fopen"); return 1; }
    }
    while (fgets(line, sizeof(line), input)) {
        if (process_command(line) < 0) break;
    }
    if (input != stdin) fclose(input);
    return 0;
}
